mapper.select:
SELECT r.*, a.code AS asset_code, a.name AS asset_name, d.name AS dept_name, v.voucher_no FROM fin_depreciation r JOIN fin_asset a ON a.id = r.asset_id LEFT JOIN sys_dept d ON d.id = a.dept_id LEFT JOIN fin_voucher v ON v.id = r.voucher_id
r.period = #{period} AND r.asset_id = #{assetId}
ORDER BY r.period DESC, a.code
